-- =====================================================================
--  EXAM QUESTION BANK — 200 MCQ (Practical Accounting Executive Course, ক্লাস ১–৮)
--  Run AFTER exam-update.sql:  Supabase → SQL Editor → New query → paste all → Run
--  Safe to run again: questions already added (same number) are skipped,
--  so your edits in the Admin Panel are never overwritten.
--  Levels: easy = জ্ঞানভিত্তিক, practical = হিসাব/প্রয়োগ, hard = একটু কঠিন
-- =====================================================================

on conflict (ref_no) where ref_no is not null do nothing;

-- Check: how many active questions per topic and level
select t.title, q.difficulty, count(*)
from public.exam_questions q join public.exam_topics t on t.id = q.topic_id
where q.status = 'active'
group by t.sort_order, t.title, q.difficulty order by t.sort_order, q.difficulty;
